import type { GridRowId, GridValidRowModel } from '../DataGrid.types';

export const AUTO_GENERATED_ID_PREFIX = 'auto-generated-row-';
export const NO_VALUE_LABEL = '(No value)';

export interface GridTreeNode<R extends GridValidRowModel> {
  id: GridRowId;
  depth: number;
  /** The data row of this node. Groups generated by the grid have none. */
  row?: R;
  label: string;
  /** Column the node groups by, for nodes created by row grouping. */
  groupField?: string;
  children: GridTreeNode<R>[];
  /** Rows in this node's subtree, itself included. */
  rowCount: number;
  /** Stands in for a row that has not been loaded yet. */
  placeholder?: boolean;
}

export function isAutoGenerated(id: GridRowId): boolean {
  return typeof id === 'string' && id.startsWith(AUTO_GENERATED_ID_PREFIX);
}

function countRows<R extends GridValidRowModel>(node: GridTreeNode<R>): number {
  node.rowCount = (node.row ? 1 : 0) + node.children.reduce((total, child) => total + countRows(child), 0);
  return node.rowCount;
}

export function buildFlatNodes<R extends GridValidRowModel>(
  rows: readonly R[],
  getId: (row: R) => GridRowId,
  isPlaceholder?: (row: R) => boolean,
): GridTreeNode<R>[] {
  return rows.map((row) =>
    isPlaceholder?.(row)
      ? { id: getId(row), depth: 0, label: '', children: [], rowCount: 0, placeholder: true }
      : { id: getId(row), depth: 0, row, label: '', children: [], rowCount: 1 },
  );
}

/** Builds the hierarchy described by `getPath`. Missing ancestors become generated groups. */
export function buildPathTree<R extends GridValidRowModel>(
  rows: readonly R[],
  getId: (row: R) => GridRowId,
  getPath: (row: R) => readonly string[],
): GridTreeNode<R>[] {
  const roots: GridTreeNode<R>[] = [];
  const byKey = new Map<string, GridTreeNode<R>>();

  for (const row of rows) {
    const path = getPath(row);
    let siblings = roots;
    path.forEach((segment, depth) => {
      const key = path.slice(0, depth + 1).join('\u0000');
      let node = byKey.get(key);
      if (!node) {
        node = {
          id: `${AUTO_GENERATED_ID_PREFIX}${path.slice(0, depth + 1).join('/')}`,
          depth,
          label: segment,
          children: [],
          rowCount: 0,
        };
        byKey.set(key, node);
        siblings.push(node);
      }
      if (depth === path.length - 1) {
        node.row = row;
        node.id = getId(row);
      }
      siblings = node.children;
    });
  }

  roots.forEach(countRows);
  return roots;
}

/** Builds one group level per field in `fields`, with the rows as leaves below the last level. */
export function buildGroupedTree<R extends GridValidRowModel>(
  rows: readonly R[],
  getId: (row: R) => GridRowId,
  fields: readonly string[],
  getGroupLabel: (row: R, field: string) => string,
): GridTreeNode<R>[] {
  const roots: GridTreeNode<R>[] = [];
  const byKey = new Map<string, GridTreeNode<R>>();

  for (const row of rows) {
    let siblings = roots;
    const trail: string[] = [];
    fields.forEach((field, depth) => {
      const label = getGroupLabel(row, field);
      trail.push(`${field}:${label}`);
      const key = trail.join('\u0000');
      let node = byKey.get(key);
      if (!node) {
        node = {
          id: `${AUTO_GENERATED_ID_PREFIX}${trail.join('/')}`,
          depth,
          label,
          groupField: field,
          children: [],
          rowCount: 0,
        };
        byKey.set(key, node);
        siblings.push(node);
      }
      siblings = node.children;
    });
    siblings.push({ id: getId(row), depth: fields.length, row, label: '', children: [], rowCount: 1 });
  }

  roots.forEach(countRows);
  return roots;
}

/**
 * Drops nodes that neither pass `keep` nor have a surviving descendant.
 * With `rootsOnly`, only the top level is tested and a kept node keeps all of its children.
 */
export function pruneTree<R extends GridValidRowModel>(
  nodes: readonly GridTreeNode<R>[],
  keep: (row: R) => boolean,
  rootsOnly = false,
): GridTreeNode<R>[] {
  const result: GridTreeNode<R>[] = [];
  for (const node of nodes) {
    if (rootsOnly) {
      // A generated group has no row of its own, so it stays when any row below it matches.
      if (node.row ? keep(node.row) : collectRows(node).some(keep)) {
        result.push(node);
      }
      continue;
    }
    const children = pruneTree(node.children, keep);
    if ((node.row && keep(node.row)) || children.length > 0) {
      const pruned = { ...node, children };
      countRows(pruned);
      result.push(pruned);
    }
  }
  return result;
}

/** Sorts every sibling list. Nodes without a row, such as generated groups, order by label. */
export function sortTree<R extends GridValidRowModel>(
  nodes: readonly GridTreeNode<R>[],
  compare: ((a: R, b: R) => number) | null,
  rootsOnly = false,
): GridTreeNode<R>[] {
  const sorted = [...nodes].sort((a, b) => {
    if (a.row && b.row) {
      return compare ? compare(a.row, b.row) : 0;
    }
    return compare || (!a.row && !b.row) ? a.label.localeCompare(b.label, undefined, { numeric: true }) : 0;
  });
  if (rootsOnly) {
    return sorted;
  }
  return sorted.map((node) => (node.children.length > 0 ? { ...node, children: sortTree(node.children, compare) } : node));
}

export function flattenTree<R extends GridValidRowModel>(
  nodes: readonly GridTreeNode<R>[],
  isExpanded: (node: GridTreeNode<R>) => boolean,
  out: GridTreeNode<R>[] = [],
): GridTreeNode<R>[] {
  for (const node of nodes) {
    out.push(node);
    if (node.children.length > 0 && isExpanded(node)) {
      flattenTree(node.children, isExpanded, out);
    }
  }
  return out;
}

/** The data rows at the bottom of the subtree: rows without children. A node without children is its own leaf. */
export function collectLeafRows<R extends GridValidRowModel>(node: GridTreeNode<R>, out: R[] = []): R[] {
  if (node.children.length === 0) {
    if (node.row) {
      out.push(node.row);
    }
    return out;
  }
  for (const child of node.children) {
    collectLeafRows(child, out);
  }
  return out;
}

/** Every data row in the subtree, the node's own row first. */
export function collectRows<R extends GridValidRowModel>(node: GridTreeNode<R>, out: R[] = []): R[] {
  if (node.row) {
    out.push(node.row);
  }
  for (const child of node.children) {
    collectRows(child, out);
  }
  return out;
}
